let memoryObserver=null,memoryMotion=true;const visibleMemories=new Set();
function hydrateMemory(v){if(!v.dataset.loaded){v.poster=v.dataset.poster;v.src=v.dataset.src;v.dataset.loaded='yes'} }
function magicAvailable(){return typeof magicGiftAvailable==='function'?magicGiftAvailable():(window.ADMIN_UNLOCKED||Boolean((C?.startDate||window.SIMULATED_START_DATE)&&unlocked(8)))}
function syncMagicMemories(){const nav=document.querySelector('[data-page="magic"]');if(nav)nav.hidden=!magicAvailable()}
function memoryInvitation(){if(!magicAvailable())return '';return `<a class="memory-invite" href="#magic"><span aria-hidden="true">🎬</span><div><h2>Büyülü video anılarımız canlanıyor.</h2><p>Birbirimize sarıldığımız, güldüğümüz ve seslerimizin yankılandığı video kayıtlarımız…</p></div><b>Videoları izle ↗</b></a>`}
function magic(){return `<section class="magic-room"><div class="magic-stars" aria-hidden="true">✧ · ✦ · ✧</div><div class="page-heading"><span class="eyebrow">Bize özel canlı anlar</span><h1>Büyülü <em>video odası.</em></h1><p>Birlikte güldüğümüz, konuştuğumuz ve anı dondurmak yerine canlandırdığımız videolarımız burada.<br>Çerçevelere dokunarak videoları sesli ve büyük ekranda izleyebilirsin.</p><button class="memory-motion" aria-pressed="false">Önizlemeleri durdur ✧</button></div><div class="portrait-wall">${enchantedMemories.map((m,i)=>`<article class="living-portrait portrait-${i} ${m.portrait?'portrait-vertical':''}"><button class="portrait-frame" data-memory="${m.id}" aria-label="${esc(m.title)} videosunu sesli ve büyük aç"><span class="portrait-corner tl" aria-hidden="true">✦</span><video style="--portrait-ratio:${m.portrait||m.id==='station'||m.id==='new-memory'?'9/16':'16/9'}" muted loop playsinline preload="none" data-poster="assets/memories/${m.id}.jpg" data-src="assets/memories/previews/${m.id}.mp4" data-memory-loop></video><span class="portrait-glow" aria-hidden="true"></span><span class="portrait-watch">Videoyu izle ▶ ♡</span><span class="portrait-corner br" aria-hidden="true">✦</span></button><div class="portrait-plaque"><small>${esc(m.type)}</small><h2>${esc(m.title)}</h2><p>${esc(m.note)}</p></div></article>`).join('')}</div><p class="magic-whisper">Kameraya sığan her saniyede ikimiz varız;<br>seninle paylaştığım her an, hayatımın en güzel videosu. ♡</p><div class="magic-candles" aria-hidden="true"><i></i><i></i><i></i></div><a class="btn secondary" href="#album">Anı günlüğümüze dön ♡</a></section>`}
function mountMagicalMemories(){if(memoryObserver)memoryObserver.disconnect();visibleMemories.clear();const videos=document.querySelectorAll('[data-memory-loop]');if(!videos.length)return;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;memoryMotion=!reduced;const toggle=document.querySelector('.memory-motion');if(toggle){toggle.setAttribute('aria-pressed',String(!memoryMotion));toggle.textContent=memoryMotion?'Önizlemeleri durdur ✧':'Videoları canlandır ✧'}memoryObserver=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{if(isIntersecting){visibleMemories.add(target);if(memoryMotion){hydrateMemory(target);target.play().catch(()=>{})}else target.poster=target.dataset.poster}else{visibleMemories.delete(target);target.pause()}}),{threshold:.1,rootMargin:'100px 0px'});videos.forEach(v=>memoryObserver.observe(v))}
document.addEventListener('click',e=>{const frame=e.target.closest('[data-memory]');if(frame){const m=enchantedMemories.find(m=>m.id===frame.dataset.memory);if(!m)return;show(`<div class="memory-viewer"><video controls autoplay playsinline poster="assets/memories/${m.id}.jpg"><source src="assets/memories/${m.id}.mp4" type="video/mp4"></video><small>${esc(m.type)}</small><h2>${esc(m.title)}</h2><p>${esc(m.note)}</p></div>`)}const toggle=e.target.closest('.memory-motion');if(toggle){memoryMotion=!memoryMotion;toggle.setAttribute('aria-pressed',String(!memoryMotion));toggle.textContent=memoryMotion?'Önizlemeleri durdur ✧':'Videoları canlandır ✧';document.querySelectorAll('[data-memory-loop]').forEach(v=>{if(memoryMotion&&visibleMemories.has(v)){hydrateMemory(v);v.play().catch(()=>{})}else v.pause()})}});
document.addEventListener('visibilitychange',()=>{document.querySelectorAll('[data-memory-loop]').forEach(v=>{if(document.hidden)v.pause();else if(memoryMotion&&visibleMemories.has(v)){hydrateMemory(v);v.play().catch(()=>{})}})});
